def traj():
    # Horizontal throw from height h with speed v: y = h - 5 x^2 / v^2.
    return {"kind": "plot", "x": [0, 'v * sqrt(h / 5) * 1.2'], "y": [0, 'h * 1.2'], "functions": [{"expr": 'h - 5 * x^2 / v^2'}], "axes": {"x": 'x, м', "y": 'y, м'}}

